use anyhow::{Result,ensure};
use glam::{Mat4,Quat,Vec3};
use std::time::{Instant,Duration};
use crate::{Prepared,gpu::Gpu,scene::{Scene,TABLE},hud::Hud,log::{Log,root},perf::GpuTimer};
pub fn run(log:&Log,prepared:Prepared)->Result<()>{
 let mut gpu=Gpu::new(log,None,0xb000)?;let mut scene=Scene::new(prepared.source,prepared.assets,&mut gpu)?;scene.seek(24600.0);scene.table_origin.z=-1.4;scene.elapsed_seconds=12.0;let mut hud=Hud::new(&scene.assets.portraits)?;let base=[1632,1760];let after=gpu.settings.eye_size(base,[8192,8192]);let fov=90f32.to_radians();let mut reports=Vec::new();
 let head=Vec3::new(0.0,1.6,0.0);let view=Mat4::look_at_rh(head,Vec3::new(0.0,TABLE,-1.4),Vec3::Y);let q=view.inverse().to_scale_rotation_translation().1;
 for (name,quality,size,samples) in [("before",false,base,1),("after",true,after,gpu.settings.msaa_samples)]{
  gpu.quality=quality;scene.reset_facing();for _ in 0..12{scene.update(&mut gpu,head,q,0.1)?;}gpu.update_hud(hud.render(&scene.hud_content()))?;let(texture,target)=gpu.offscreen_samples(size[0],size[1],samples)?;ensure!(target.samples==samples,"요청 MSAA 샘플 수 미지원");let projection=Mat4::perspective_rh(fov,base[0]as f32/base[1]as f32,0.01,40.0);
  for i in 0..9{let shifted=head+Vec3::X*((i as f32-4.0)*0.0015);let view=Mat4::from_rotation_translation(q,shifted).inverse();scene.update(&mut gpu,shifted,q,1.0/120.0)?;gpu.render(&target,projection*view,scene.world(),true);gpu.save_png(&texture,&root().join(format!("_tmp/shots/native_quality_{name}_{i:02}.png")))?;}
  reports.push(serde_json::json!({"name":name,"resolution":size,"samples":target.samples,"pixelFilter":if quality{"sharp bilinear / anisotropic16x / cell-local premultiplied mip"}else{"point / mip0"}}));
 }
 gpu.quality=true;scene.show_hud=false;scene.table_origin=Vec3::ZERO;let(texture,target)=gpu.offscreen(1600,1100)?;let(head,q,view)=crate::capture::camera(0.0,42.0,3.7);let vp=Mat4::perspective_rh(42f32.to_radians(),1600.0/1100.0,0.01,40.0)*view;let hash=scene.terrain_hash();let mut rotations=Vec::new();
 for degrees in [0,90,180,270]{scene.table_yaw=(degrees as f32).to_radians();scene.reset_facing();for _ in 0..12{scene.update(&mut gpu,head,q,0.1)?;}gpu.mask(|_|true);gpu.render(&target,vp,scene.world(),true);gpu.save_png(&texture,&root().join(format!("_tmp/shots/native_table_yaw_{degrees}.png")))?;let max_bar=scene.healthbar_screen_angles(vp).into_iter().map(f32::abs).fold(0.0f32,f32::max);let feet:Vec<_>=scene.source.frame(24600).entities.iter().filter(|r|scene.source.manifest().catalog[&r.0].kind=="champion").map(|r|scene.sprite_measure(r.0,vp,1100).unwrap()).collect();ensure!(max_bar<0.01&&feet.iter().all(|f|f["footError"].as_f64().unwrap()<1e-5),"회전시 발/체력바 오차");ensure!(scene.terrain_hash()==hash,"회전에서 원본 지형 메시 변경");let depth=crate::validation::rotation_depth(&scene,&mut gpu,&texture,&target,vp,head)?;rotations.push(serde_json::json!({"degrees":degrees,"feet":feet,"maxBarAngleDeg":max_bar,"depth":depth}));}
 // 양안과 같은 두 번의 렌더 비용. 실제 런타임/압축/디스플레이 비용은 포함하지 않는다.
 scene.table_yaw=0.0;scene.table_origin.z=-1.4;let (_,target)=gpu.offscreen(after[0],after[1])?;let head=Vec3::new(0.0,1.6,0.0);let view=Mat4::look_at_rh(head,Vec3::new(0.0,TABLE,-1.4),Vec3::Y);let q=view.inverse().to_scale_rotation_translation().1;let vp=Mat4::perspective_rh(fov,base[0]as f32/base[1]as f32,0.01,40.0)*view;let mut timer=GpuTimer::new(&gpu.device)?;let mut cpu=Vec::new();let mut gpu_times=Vec::new();for i in 0..240{let start=Instant::now();if let Some(ms)=timer.begin(&gpu.context)?{if i>30{gpu_times.push(ms);}}scene.update(&mut gpu,head,q,1.0/120.0)?;gpu.render(&target,vp,scene.world(),true);gpu.render(&target,vp,scene.world(),true);timer.end(&gpu.context);unsafe{gpu.context.Flush();}if i>30{cpu.push(start.elapsed().as_secs_f64()*1000.0);}if start.elapsed()<Duration::from_secs_f64(1.0/120.0){std::thread::sleep(Duration::from_secs_f64(1.0/120.0)-start.elapsed());}}
 gpu.check()?;let report=serde_json::json!({"검증":"통과","eyeResolutionSource":"사용자 전달 1632x1760","verticalFovDeg":90,"Fov주의":"실제 런타임 FOV를 측정하지 않은 고정90도 비교 카메라","headTranslationStepMm":1.5,"framesPerMode":9,"reports":reports,"rotations":rotations,"twoEyeCpuMs":cpu,"twoEyeGpuMs":gpu_times,"hudResolution":[hud.width,hud.height],"실기기":"이번 화질·잡기 수정본 미검증, Link 설정 변경 없음"});std::fs::write(root().join("_tmp/logs/native_quality_capture.json"),serde_json::to_vec_pretty(&report)?)?;log.line("눈 해상도 화질 비교/1.5mm 연속/4방향 테이블/양안 비용 검증 완료");Ok(())
}
